package org.itantra.core.tts

/**
 * Domain representation of synthesized audio generated by [TtsEngine].
 *
 * Encapsulates raw PCM float samples and stream format metadata, decoupled from
 * hardware playback sinks (such as Android AudioTrack).
 *
 * @property samples Raw PCM audio samples normalized to [-1.0, +1.0] float range.
 * @property sampleRate Audio sampling rate in Hertz (e.g. 16000 or 22050).
 * @property channelCount Number of audio channels (1 for Mono).
 * @property sampleFormat Description of the sample representation format ("PCM_FLOAT").
 */
data class TtsAudio(
    val samples: FloatArray,
    val sampleRate: Int,
    val channelCount: Int = 1,
    val sampleFormat: String = "PCM_FLOAT"
) {
    /**
     * Total number of audio samples.
     */
    val sampleCount: Int
        get() = samples.size

    /**
     * Computed audio duration in seconds based on sample count and sample rate.
     */
    val durationSeconds: Float
        get() = if (sampleRate > 0) samples.size.toFloat() / sampleRate else 0.0f

    init {
        require(sampleRate > 0) { "sampleRate must be positive, got: $sampleRate" }
        require(channelCount > 0) { "channelCount must be positive, got: $channelCount" }
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as TtsAudio

        if (!samples.contentEquals(other.samples)) return false
        if (sampleRate != other.sampleRate) return false
        if (channelCount != other.channelCount) return false
        if (sampleFormat != other.sampleFormat) return false

        return true
    }

    override fun hashCode(): Int {
        var result = samples.contentHashCode()
        result = 31 * result + sampleRate
        result = 31 * result + channelCount
        result = 31 * result + sampleFormat.hashCode()
        return result
    }

    override fun toString(): String {
        return "TtsAudio(sampleCount=$sampleCount, sampleRate=$sampleRate Hz, " +
                "channels=$channelCount, format=$sampleFormat, duration=${String.format("%.3f", durationSeconds)}s)"
    }
}

/**
 * Exception thrown when synthesis is requested for an unsupported language.
 */
class UnsupportedTtsLanguageException(
    val language: String,
    message: String = "Language '$language' is not supported by the offline TTS engine"
) : IllegalArgumentException(message)

/**
 * Exception thrown when TTS operations are attempted before initialization or after release.
 */
class TtsEngineNotInitializedException(
    message: String = "TTS engine is not initialized or has already been released"
) : IllegalStateException(message)
